/* Six self-contained recreational modules, discovered by the shared workspace. */
(async function() {
  'use strict';
  const E=window.NorthstarGamesEngine;
  const titles={chess:'Chess',euchre:'Euchre'};
  const rules={
    chess:'Drag a piece onto a highlighted square, or select the piece and then its destination. White moves first. Legal moves, castling, en passant, check, checkmate and draws are enforced. Choose a promotion piece before moving your pawn to the last rank. Choose an opponent in game setup. Start at 500 Elo. Checkmate each bot to unlock the next level.',
    checkers:'American checkers. Red moves first. Men move and capture diagonally forward; kings move both ways. Captures are compulsory and multiple jumps must be completed. Crowning ends the turn. No legal move loses; 40 moves each without capture or crowning is a draw.',
    go:'9 × 9 Go. Black moves first; White receives 6.5 komi. Surround groups to capture them. Suicide and repeated board positions are forbidden. Play out disputed or dead groups before passing: no automatic dead-stone removal. Two passes finish the game with area scoring (stones plus surrounded empty points). Computer plays White at beginner strength.',
    poker:'Five-card draw against the computer. Each player starts with 100 play chips and antes 5 per hand. Select any cards to replace once, then draw and reveal. Highest five-card hand takes the 10-chip pot; equal hands split. This casual variant has no betting rounds. No real money.',
    pool:'Race the NorthStar Bot to pocket the most balls, or choose Solo practice. Click or tap the table to aim from the white cue ball, set power, then Shoot. In bot mode, pocketed balls score one point and turns alternate after each shot. A scratch respots the cue ball and ends the turn. Simplified friction and elastic collisions; no spin or eight-ball rules.',
    euchre:'You and North (your computer partner) play East and West. First team to 10 wins. A 24-card deck, five cards each. Order up the turned suit or pass; second round chooses another suit (dealer must call). Dealer picks up and discards in round one. Right and left bowers are highest trump; follow effective suit. Makers need 3 tricks for 1 point, all 5 for 2, or 4 when alone; being euchred gives opponents 2. Going alone sits out your partner.'
  };
  const root=document.createElement('section');root.id='games';root.className='section';
  const chessStrengths=[[500,'Beginner'],[750,'Learning'],[900,'Decent'],[1000,'Solid'],[1150,'Good'],[1200,'Intermediate'],[1400,'Strong'],[1650,'Very good'],[1800,'Advanced'],[2000,'Elite'],[2150,'Pro'],[2300,'Master'],[2500,'GM']];
  root.innerHTML=Object.entries(titles).map(([id,title])=>`<article class="panel ng-game" data-module-id="${id}" id="ng-${id}"><h2>${title}</h2><p class="ng-note">${id==='euchre'?'Your bot partner against two bot opponents':id==='poker'?'Head-to-head against the NorthStar Bot':id==='pool'?'Play against the NorthStar Bot or practise solo':'Play against the NorthStar Bot or choose two players'}</p><div class="ng-toolbar"><button type="button" data-new>New game</button>${['chess','checkers','go','pool'].includes(id)?'<label>Mode <select data-mode><option value="computer">Vs NorthStar Bot</option><option value="local">'+(id==='pool'?'Solo practice':'Two players')+'</option></select></label>':''}${id==='chess'?`<label>Promote to <select data-promotion><option value="q">Queen</option><option value="r">Rook</option><option value="b">Bishop</option><option value="n">Knight</option></select></label>`:''}</div><div class="ng-status" role="status" aria-live="polite"></div><div class="ng-play"></div><details><summary>How to play</summary><p>${rules[id]}</p></details></article>`).join('');
  const anchor=document.querySelector('#training')||document.querySelector('main .section');if(!anchor)return;anchor.parentElement.append(root);
  const nav=document.querySelector('#sideNav');if(nav&&!nav.querySelector('[data-tab="games"]')){const b=document.createElement('button');b.type='button';b.dataset.tab='games';b.textContent='Games';nav.append(b);}
  const align=()=>root.style.setProperty('--ng-left',Math.max(12,(document.querySelector('#nsStatusBar')?.getBoundingClientRect().left??180)+12)+'px');
  window.addEventListener('resize',align);requestAnimationFrame(align);
  const bar=document.querySelector('#nsStatusBar');if(bar)new ResizeObserver(align).observe(bar);
  const symbol={S:'♠',H:'♥',C:'♣',D:'♦'},rank=r=>({11:'J',12:'Q',13:'K',14:'A'}[r]||r),cardName=c=>rank(c.r)+symbol[c.s];
  const card=(c,i,selected=false,hidden=false,disabled=false)=>`<button type="button" class="ng-card ${hidden?'back':c.s==='H'||c.s==='D'?'red':''} ${selected?'selected':''}" data-card="${i}" ${disabled?'disabled':''} aria-label="${hidden?'Hidden card':cardName(c)}" aria-pressed="${selected}">${hidden?'?':cardName(c)}${selected?'<small>REPLACE</small>':''}</button>`;
  const state={},timers={};
  function pane(id){return root.querySelector('#ng-'+id);}
  function status(id,s){pane(id).querySelector('.ng-status').textContent=s;}
  // Original recovered Yahoo icons are embedded to preserve native pixels and avoid new server routes.
  const classicAvatars=[{"id":"classic-00","name":"Green alien in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-01","name":"Blonde ponytail in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-02","name":"Blue horned face with goatee","src":"data:image/png;base64,"},{"id":"classic-03","name":"Blonde hair in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-04","name":"Short brown hair in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-05","name":"Dark pigtails in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-06","name":"Smiling sunflower","src":"data:image/png;base64,"},{"id":"classic-07","name":"Long brown hair in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-08","name":"Brown pigtails in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-09","name":"Short hair in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-10","name":"White beard in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-11","name":"Dark complexion in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-12","name":"Blue Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-13","name":"Glasses and goatee in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-14","name":"Headphones and red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-15","name":"Glasses in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-16","name":"Orange bird in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-17","name":"Panda in red Yahoo cap","src":"data:image/png;base64,"},{"id":"classic-18","name":"Black hair in twin buns","src":"data:image/png;base64,"},{"id":"classic-19","name":"Short brown hair","src":"data:image/png;base64,"},{"id":"classic-20","name":"Swept black hair","src":"data:image/png;base64,"},{"id":"classic-21","name":"Brown braids","src":"data:image/png;base64,"},{"id":"classic-22","name":"Bright pink spiky hair","src":"data:image/png;base64,"},{"id":"classic-23","name":"Short hair and green collar","src":"data:image/png;base64,"},{"id":"classic-24","name":"White hair and beard","src":"data:image/png;base64,"},{"id":"classic-25","name":"Black bob with pink clip","src":"data:image/png;base64,"},{"id":"classic-26","name":"Green mohawk","src":"data:image/png;base64,"},{"id":"classic-27","name":"Black hair and yellow glasses","src":"data:image/png;base64,"},{"id":"classic-28","name":"Blonde flat-top","src":"data:image/png;base64,"},{"id":"classic-29","name":"Brown hair with whiskers","src":"data:image/png;base64,"},{"id":"classic-30","name":"Red and gold dragon","src":"data:image/png;base64,"},{"id":"classic-31","name":"Gray bun and glasses","src":"data:image/png;base64,"},{"id":"classic-32","name":"Brown hair and pink glasses","src":"data:image/png;base64,"},{"id":"classic-33","name":"Brown hair with green clips","src":"data:image/png;base64,"},{"id":"classic-34","name":"White spiky hair and red sunglasses","src":"data:image/png;base64,"},{"id":"classic-35","name":"Red bandanna and eyepatch","src":"data:image/png;base64,"},{"id":"classic-36","name":"Metal helmet and blue visor","src":"data:image/png;base64,"},{"id":"classic-37","name":"Long blonde hair","src":"data:image/png;base64,"},{"id":"classic-38","name":"Red helmet and blue visor","src":"data:image/png;base64,"},{"id":"classic-39","name":"Red spiky hair and broad grin","src":"data:image/png;base64,"},{"id":"classic-40","name":"Pink pig face","src":"data:image/png;base64,"},{"id":"classic-41","name":"Black hair and pale face","src":"data:image/png;base64,"},{"id":"classic-42","name":"Blonde hair and large blue glasses","src":"data:image/png;base64,"},{"id":"classic-43","name":"Blue hair and halo","src":"data:image/png;base64,"},{"id":"classic-44","name":"Brown hair, black sunglasses and moustache","src":"data:image/png;base64,"}];
  const chessPane=pane('chess'),toolbar=chessPane.querySelector('.ng-toolbar');
  chessPane.style.setProperty('--ng-classic-piece-atlas','url(data:image/png;base64,)');
  const savedControls={mode:toolbar.querySelector('[data-mode]'),promotion:toolbar.querySelector('[data-promotion]').parentElement};
  toolbar.innerHTML='<div class="ng-match-setup"><h3>Deep Blue Challenge</h3><label>Game type <span data-mode-slot></span></label><label>Bot level <select data-bot-level></select></label><label data-custom-box hidden>Bot Elo <input type="number" data-custom-elo required min="500" step="1"></label><button type="button" data-new>Start game</button><small data-unlock-note></small></div><div class="ng-table-actions"><button type="button" data-undo>Request takeback</button><button type="button" data-resign>Resign</button><button type="button" data-draw-offer>Offer draw</button><button type="button" data-help>Help</button><a href="/" class="ng-classic-button">Quit</a></div><details class="ng-game-settings"><summary>Game options</summary><label><input type="checkbox" data-last-move> Highlight last move</label><div data-settings-slot></div></details>';
  savedControls.mode.options[0].textContent='Deep Blue Challenge';
  savedControls.mode.add(new Option('Unranked practice','practice'),1);
  toolbar.querySelector('[data-mode-slot]').append(savedControls.mode);
  toolbar.querySelector('[data-settings-slot]').append(savedControls.promotion);
  const level=toolbar.querySelector('[data-bot-level]'),custom=toolbar.querySelector('[data-custom-elo]');
  let playerKey='guest',ceiling=500;
  function historyKey(){return 'northstar-chess-unlocked:'+playerKey;}
  function setupChoices(){
    const practice=savedControls.mode.value==='practice';
    const selected=level.value;
    level.replaceChildren();
    for(const [rating,label] of chessStrengths){
      if(!practice&&rating>ceiling)continue;
      level.add(new Option(label+' · '+rating,rating));
    }
    if(practice)level.add(new Option('Custom Elo','custom'));
    if([...level.options].some(o=>o.value===selected))level.value=selected;
    custom.max=3190;custom.min=500;
    updateSetup();
  }
  function updateSetup(){
    const bot=savedControls.mode.value!=='local';
    level.parentElement.hidden=!bot;
    custom.parentElement.hidden=!bot||level.value!=='custom';
    const next=chessStrengths.find(([rating])=>rating>ceiling);
    toolbar.querySelector('[data-unlock-note]').textContent=savedControls.mode.value==='practice'?'Practice with any bot or enter an Elo from 500 to 3190.':bot?(next?'Beat the '+ceiling+' bot to unlock '+next[1]+' ('+next[0]+').':'All bot levels unlocked.'):'';
  }
  function loadProgress(){
    playerKey=chessPane.ownerDocument.querySelector('.ns-invite-bar')?.dataset.chessAccount||'guest';
    if(state.chess&&!state.chess.game.history().length)state.chess.playerKey=playerKey;
    ceiling=500;
    try{const n=Number(localStorage.getItem(historyKey()));if(n>=500&&chessStrengths.some(([v])=>v===n))ceiling=n;}catch{}
    setupChoices();
  }
  loadProgress();
  window.addEventListener('northstar:chess-identity',()=>{loadProgress();if(state.chess){review=null;renderBoard('chess');}});
  window.addEventListener('storage',e=>{if(e.key===historyKey())loadProgress();});
  level.onchange=()=>{if(level.value==='custom'&&!custom.value)custom.value=ceiling;updateSetup();};
  savedControls.mode.onchange=setupChoices;
  function advance(s){
    if(!s.challenge||s.playerKey!==playerKey||s.strength!==ceiling||!s.game.isCheckmate()||s.game.turn()!=='b')return;
    const next=chessStrengths.find(([rating])=>rating>ceiling);
    if(!next)return;
    ceiling=next[0];
    try{localStorage.setItem(historyKey(),String(ceiling));}catch{}
    setupChoices();
  }
  toolbar.setAttribute('aria-label','Chess controls');
  toolbar.querySelector('[data-help]').onclick=()=>{const help=chessPane.querySelector(':scope > details');help.open=!help.open;if(help.open)help.scrollIntoView({block:'nearest'});};
  const chessRail=document.createElement('aside');chessRail.className='ng-chess-rail';
  chessRail.setAttribute('aria-label','Players and move history');
  const playerPanel=color=>`<div class="ng-player" data-player="${color}"><small>${color==='b'?'Black':'White'}</small><div class="ng-player-identity"><button type="button" class="ng-avatar-button" data-avatar-player="${color}" aria-label="Choose ${color==='b'?'Black':'White'} avatar"><img width="34" height="23" alt=""></button><strong data-${color==='b'?'black':'white'}-name></strong><span class="ng-turn-marker" aria-label="Current turn">⬅</span></div></div>`;
  chessRail.innerHTML=playerPanel('b')+'<div class="ng-history-navigation"><button type="button" data-history-top aria-label="First moves">◀</button><span></span><button type="button" data-history-bottom aria-label="Latest moves">▶</button></div><div class="ng-history-scroll" tabindex="0" aria-label="Scrollable move history"><table class="ng-history"><thead><tr><th scope="col" aria-label="Move number"></th><th scope="col">White</th><th scope="col">Black</th></tr></thead><tbody></tbody></table></div><button type="button" class="ng-classic-button ng-invite" data-ns-invite>Invite</button>'+playerPanel('w');
  chessPane.append(chessRail);
  const lower=document.createElement('div');lower.className='ng-table-bottom';
  lower.innerHTML='<div class="ng-chat-host"><div class="ng-local-chat"><div class="ng-table-log" role="log" aria-label="Table chat messages" tabindex="0"><div class="ng-chat-notice">Local table chat</div></div><form class="ng-chat-compose"><label class="ng-sr-only" for="ngChessChatInput">Chat message</label><input id="ngChessChatInput" name="message" maxlength="500" autocomplete="off" placeholder="Type a message…"><button type="submit">Send</button></form></div></div><div class="ng-table-players" aria-label="Players at this table"><table><tbody></tbody></table></div>';
  lower.querySelector('.ng-chat-compose').onsubmit=event=>{
    event.preventDefault();const input=lower.querySelector('[name="message"]'),text=input.value.trim();if(!text)return;
    const entry=document.createElement('div');entry.className='ng-chat-message';
    const avatar=document.createElement('img');avatar.src=classicAvatars[avatarChoice.w].src;avatar.width=34;avatar.height=23;avatar.alt='';
    const name=document.createElement('strong');name.textContent='You: ';
    const body=document.createElement('span');body.textContent=text;
    entry.append(avatar,name,body);const log=lower.querySelector('.ng-table-log');log.append(entry);while(log.children.length>100)log.children[0].remove();log.scrollTop=log.scrollHeight;input.value='';input.focus();
  };
  function mountSharedChessChat(){
    const host=lower.querySelector('.ng-chat-host');if(host.dataset.shared==='true'||typeof window.NorthStarSharedChat?.mount!=='function')return;
    try{const frame=window.NorthStarSharedChat.mount(host,{theme:'classic',compact:true});if(frame){host.dataset.shared='true';lower.querySelector('.ng-local-chat').hidden=true;}}catch{}
  }
  mountSharedChessChat();
  document.addEventListener('DOMContentLoaded',mountSharedChessChat,{once:true});window.addEventListener('load',mountSharedChessChat,{once:true});window.addEventListener('northstar:chat-ready',mountSharedChessChat);

  chessPane.append(lower);
  const avatarChoice={w:2,b:12};
  try{const saved=JSON.parse(localStorage.getItem('northstar-chess-classic-avatars')||'null');for(const color of ['w','b'])if(Number.isInteger(saved?.[color])&&classicAvatars[saved[color]])avatarChoice[color]=saved[color];}catch{}
  function paintAvatars(){for(const color of ['w','b']){const item=classicAvatars[avatarChoice[color]],img=chessRail.querySelector(`[data-avatar-player="${color}"] img`);img.src=item.src;img.alt=item.name;}try{localStorage.setItem('northstar-chess-classic-avatars',JSON.stringify(avatarChoice));}catch{}}
  paintAvatars();
  window.addEventListener('northstar:avatar-change',event=>{
    const avatarId=event.detail?.avatarId;
    if(typeof avatarId!=='string')return;
    const index=classicAvatars.findIndex(item=>item.id===avatarId);
    if(index<0)return;
    avatarChoice.w=index;paintAvatars();
  });
  const chooser=document.createElement('dialog');chooser.className='ng-avatar-chooser';
  chooser.innerHTML='<form method="dialog"><strong>Choose a classic avatar</strong><button aria-label="Close avatar picker">×</button></form><div class="ng-avatar-grid"></div><p>Recovered Yahoo Classic Games icons · original pixels</p>';
  chessPane.append(chooser);
  let choosing='w';
  classicAvatars.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.title=item.name;button.setAttribute('aria-label',item.name);button.innerHTML=`<img src="${item.src}" width="34" height="23" alt="">`;button.onclick=()=>{avatarChoice[choosing]=index;paintAvatars();chooser.close();};chooser.querySelector('.ng-avatar-grid').append(button);});
  chessRail.querySelectorAll('[data-avatar-player]').forEach(button=>button.onclick=()=>{
    choosing=button.dataset.avatarPlayer;
    if(choosing==='w'&&typeof window.NorthStarSharedChat?.chooseAvatar==='function'){
      window.NorthStarSharedChat.chooseAvatar();return;
    }
    chooser.querySelectorAll('.ng-avatar-grid button').forEach((item,i)=>item.setAttribute('aria-pressed',String(i===avatarChoice[choosing])));chooser.showModal();
  });
  chessRail.querySelector('[data-history-top]').onclick=()=>chessRail.querySelector('.ng-history-scroll').scrollTo({top:0});
  chessRail.querySelector('[data-history-bottom]').onclick=()=>{const el=chessRail.querySelector('.ng-history-scroll');el.scrollTo({top:el.scrollHeight});};
  toolbar.querySelector('[data-last-move]').onchange=()=>{if(state.chess)renderBoard('chess');};
  toolbar.querySelector('[data-undo]').onclick=()=>{
    const s=state.chess;
    if(!s||s.challenge||!s.game.history().length)return;
    if(s.mode==='local'){
      const opponent=s.game.turn()==='w'?'White':'Black';
      if(!confirm(opponent+', accept the takeback request?'))return;
    }
    cancelBot();clearTimeout(timers.chess);
    s.game.undo();
    if(s.mode==='computer'&&s.game.turn()==='b')s.game.undo();
    s.selected=null;s.result=null;renderBoard('chess');
  };
  toolbar.querySelector('[data-resign]').onclick=()=>{const s=state.chess;if(!s||!confirm('Resign this game?'))return;cancelBot();clearTimeout(timers.chess);s.result=(s.mode==='computer'||s.game.turn()==='w'?'Black':'White')+' wins by resignation';s.selected=null;renderBoard('chess');};
  toolbar.querySelector('[data-draw-offer]').onclick=()=>{const s=state.chess;if(!s||s.mode!=='local'||!confirm('Do both players agree to a draw?'))return;clearTimeout(timers.chess);s.result='Draw by agreement';s.selected=null;renderBoard('chess');};
  function renderChessHistory(g,s){
    const moves=g.history({verbose:true}),body=chessRail.querySelector('tbody'),names={w:s.mode==='local'?'Player 1':'You',b:s.mode==='local'?'Player 2':(s.challenge?'Challenge':'Unranked')+' bot · '+s.strength+' Elo'};
    const signature=moves.map(m=>m.san).join(' '),changed=body.dataset.moves!==signature;
    const notation=m=>m?`${m.from}-${m.to}${m.promotion?'='+m.promotion.toUpperCase():''}`:'';
    if(changed)body.innerHTML=Array.from({length:Math.ceil(moves.length/2)},(_,i)=>`<tr><th scope="row">${i+1}</th><td>${notation(moves[i*2])}</td><td>${notation(moves[i*2+1])}</td></tr>`).join('');
    body.dataset.moves=signature;
    chessRail.querySelector('[data-black-name]').textContent=names.b;
    chessRail.querySelector('[data-white-name]').textContent=names.w;
    const ended=!!s.result||g.isGameOver();
    chessRail.querySelectorAll('[data-player]').forEach(el=>el.classList.toggle('is-turn',!ended&&el.dataset.player===g.turn()));
    const takeback=toolbar.querySelector('[data-undo]');
    takeback.disabled=!!review||s.challenge||!moves.length;
    takeback.title=s.challenge?'Challenge games require each move to stand.':s.mode==='local'?'Ask the other player to undo the last move.':'The practice bot accepts automatically.';
    toolbar.querySelector('[data-resign]').disabled=ended||!!review;
    toolbar.querySelector('[data-draw-offer]').disabled=ended||!!review||s.mode!=='local';
    toolbar.querySelector('[data-draw-offer]').title=s.mode==='local'?'Agree to a draw with the other local player':'Draw offers are available in two-player mode';
    lower.querySelector('.ng-table-players tbody').innerHTML=`<tr><td>${names.b}</td><td>${s.mode==='local'?'Local':'Bot'}</td></tr><tr><td>${names.w}</td><td>Local</td></tr>`;
    if(changed){const scroller=chessRail.querySelector('.ng-history-scroll');scroller.scrollTop=scroller.scrollHeight;}
    chessPane.querySelector('.ng-status').dataset.local='true';
  }

  const engineToggle=document.createElement('label');engineToggle.className='ng-check';
  engineToggle.innerHTML='<input type="checkbox" data-engine-analysis> Engine analysis';
  toolbar.querySelector('.ng-game-settings').before(engineToggle);
  const enginePanel=document.createElement('section');enginePanel.className='ng-engine-panel';enginePanel.hidden=true;
  enginePanel.setAttribute('aria-label','Chess engine evaluation');
  enginePanel.innerHTML='<div class="ng-engine-heading"><strong>Stockfish 18</strong><output data-evaluation aria-live="polite"></output></div><small data-engine-state>White advantage is positive</small><ol data-engine-lines></ol>';
  engineToggle.after(enginePanel);
  const reviewBar=document.createElement('div');
  reviewBar.className='ng-review-controls';
  reviewBar.innerHTML='<label>Game review <select data-review-game><option value="">Current game</option></select></label><button type="button" data-review-back>Back one move</button><select data-review-ply aria-label="Review position"></select><button type="button" data-review-next>Forward</button><button type="button" data-review-live>Return to game</button>';
  engineToggle.before(reviewBar);
  const archiveSelect=reviewBar.querySelector('[data-review-game]'),plySelect=reviewBar.querySelector('[data-review-ply]');
  const comparison=document.createElement('p');comparison.className='ng-comparison';enginePanel.append(comparison);
  let review=null,archive=[],archiveOwner=null,plySignature='';
  function saveReviewGame(s,moves){
    if(archiveOwner!==playerKey){
      archiveOwner=playerKey;archive=[];
      try{const saved=JSON.parse(localStorage.getItem('chess-replays:'+playerKey));if(Array.isArray(saved))archive=saved;}catch{}
      refreshArchiveList(s);
    }
    if(!moves.length&&!s.archiveId||s.playerKey!==playerKey)return;
    if(!s.archiveId)s.archiveId=crypto.randomUUID();
    const signature=moves.map(m=>m.san).join(' ')+'|'+(s.result||'');
    if(s.archiveSignature===signature)return;
    s.archiveSignature=signature;
    archive=archive.filter(item=>item.id!==s.archiveId);
    if(moves.length)archive.unshift({id:s.archiveId,date:new Date().toLocaleString(),pgn:s.game.pgn(),opponent:s.mode==='local'?'Two players':s.strength+' Elo',count:moves.length});
    archive=archive.slice(0,30);
    try{localStorage.setItem('chess-replays:'+playerKey,JSON.stringify(archive));}catch{}
    refreshArchiveList(s);
  }
  function refreshArchiveList(s){
    const selected=archiveSelect.value;
    archiveSelect.replaceChildren(new Option('Current game',''));
    for(const item of archive.filter(item=>item.id!==s.archiveId))archiveSelect.add(new Option(item.date+' · '+item.opponent+' · '+item.count+' plies',item.id));
    archiveSelect.value=selected;
  }
  function reviewPosition(moves,index){
    if(!moves.length)return;
    clearTimeout(timers.chess);cancelBot();
    index=Math.max(0,Math.min(index,moves.length));
    const move=moves[index];
    review={moves,index,move,position:new Chess(move?move.before:moves.at(-1).after)};
    engineToggle.querySelector('input').checked=true;
    renderBoard('chess');
  }
  function returnToGame(){
    review=null;archiveSelect.value='';renderBoard('chess');
  }
  archiveSelect.onchange=()=>{
    const item=archive.find(item=>item.id===archiveSelect.value);
    if(!item){returnToGame();return;}
    const replay=new Chess();replay.loadPgn(item.pgn);reviewPosition(replay.history({verbose:true}),0);
  };
  reviewBar.querySelector('[data-review-back]').onclick=()=>{
    const moves=review?.moves||state.chess.game.history({verbose:true});
    reviewPosition(moves,(review?.index??moves.length)-1);
  };
  reviewBar.querySelector('[data-review-next]').onclick=()=>reviewPosition(review.moves,review.index+1);
  reviewBar.querySelector('[data-review-live]').onclick=returnToGame;
  plySelect.onchange=()=>reviewPosition(review?.moves||state.chess.game.history({verbose:true}),Number(plySelect.value));
  function updateReviewControls(s){
    const moves=review?.moves||s.game.history({verbose:true}),index=review?.index??moves.length;
    const signature=moves.map(m=>m.san).join(' ');
    if(signature!==plySignature||!plySelect.length){
      plySignature=signature;
      plySelect.replaceChildren(...moves.map((m,i)=>new Option('Before '+m.before.split(' ')[5]+(m.color==='w'?'. ':'… ')+m.san,i)),new Option('Latest position',moves.length));
    }
    plySelect.value=index;plySelect.disabled=!moves.length;
    reviewBar.querySelector('[data-review-back]').disabled=!index;
    reviewBar.querySelector('[data-review-next]').disabled=!review||index===moves.length;
    reviewBar.querySelector('[data-review-live]').disabled=!review;
  }
  function describeMove(best,played,move){
    const label=(move.color==='w'?'White':'Black')+' played '+move.san;
    if(best.uci===move.lan)return label+' · Engine’s first choice.';
    if(!played)return label+' · Comparing with '+best.san.split(' ')[0]+'…';
    const alternative=' Best was '+best.san.split(' ')[0]+' ('+best.label+').';
    if(best.kind==='mate'||played.kind==='mate'){
      const reason=played.kind==='mate'&&played.cp<0&&best.kind!=='mate'?' · Allows forced mate':best.kind==='mate'&&best.cp>0&&played.kind!=='mate'?' · Misses forced mate':'';
      return label+' ('+played.label+')'+reason+'.'+alternative;
    }
    const loss=Math.max(0,(best.cp-played.cp)/100);
    const verdict=loss>=2?'Blunder':loss>=1?'Mistake':loss>=0.5?'Inaccuracy':'Close alternative';
    return label+' ('+played.label+') · '+verdict+' · estimated loss '+loss.toFixed(2)+' pawns.'+alternative;
  }
  let engineWorker=null,engineTimer=0,engineGeneration=0,engineFen='',engineMoves=[],engineWatchdog=0;
  function stopChessEngine(){clearTimeout(engineTimer);clearTimeout(engineWatchdog);engineWorker?.terminate();engineWorker=null;engineGeneration++;}
  function drawEngineArrow(){
    chessPane.querySelector('.ng-engine-arrow')?.remove();
    if(!engineToggle.querySelector('input').checked||!engineMoves[0]?.uci)return;
    const move=engineMoves[0].uci,board=chessPane.querySelector('.ng-board');if(!board)return;
    const point=square=>['abcdefgh'.indexOf(square[0])+.5,8-Number(square[1])+.5];
    const [x1,y1]=point(move.slice(0,2)),[x2,y2]=point(move.slice(2,4));
    const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('ng-engine-arrow');svg.setAttribute('viewBox','0 0 8 8');svg.setAttribute('aria-hidden','true');
    svg.innerHTML=`<defs><marker id="ngEngineArrowHead" markerWidth="3" markerHeight="3" refX="2.3" refY="1.5" orient="auto"><path d="M0 0 3 1.5 0 3z" fill="#f6c344"/></marker></defs><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#f6c344" stroke-width=".13" stroke-linecap="round" marker-end="url(#ngEngineArrowHead)"/>`;
    board.append(svg);
  }
  function updateChessAnalysis(g,s){
    const enabled=engineToggle.querySelector('input').checked;enginePanel.hidden=!enabled;
    if(!enabled){stopChessEngine();engineFen='';engineMoves=[];drawEngineArrow();return;}
    const fen=g.fen(),playedMove=review?.move,analysisKey=fen+'|'+(playedMove?.lan||'');
    comparison.textContent=playedMove?(engineFen===analysisKey?comparison.textContent:'Played '+playedMove.san+' · analysing…'):'';
    if((!review&&s.result)||g.isGameOver()){
      stopChessEngine();engineFen='';engineMoves=[];drawEngineArrow();
      enginePanel.querySelector('[data-engine-lines]').replaceChildren();
      enginePanel.querySelector('[data-evaluation]').textContent=g.isCheckmate()?(g.turn()==='w'?'0–1':'1–0'):g.isDraw()?'½–½':'Finished';
      enginePanel.querySelector('[data-engine-state]').textContent=s.result||'Game over';return;
    }
    if(engineFen===analysisKey){drawEngineArrow();return;}
    stopChessEngine();engineFen=analysisKey;engineMoves=[];drawEngineArrow();
    enginePanel.querySelector('[data-engine-lines]').replaceChildren();
    const score=enginePanel.querySelector('[data-evaluation]'),statusText=enginePanel.querySelector('[data-engine-state]');
    score.textContent='…';statusText.textContent='Analysing · White advantage is positive';
    const generation=engineGeneration,whiteSign=g.turn()==='w'?1:-1;
    const fail=()=>{if(generation!==engineGeneration)return;stopChessEngine();engineMoves=[];drawEngineArrow();score.textContent='Unavailable';statusText.textContent='Toggle analysis off and on to retry.';};
    engineTimer=setTimeout(()=>{
      if(generation!==engineGeneration)return;
      try{
        const worker=new Worker('/vendor/stockfish/stockfish-18-lite-single.js');engineWorker=worker;
        engineWatchdog=setTimeout(fail,20000);worker.onerror=fail;
        let checkingPlayed=false;
        worker.onmessage=event=>{
          if(generation!==engineGeneration||engineFen!==analysisKey)return;
          for(const line of String(event.data).split('\n')){
            if(line==='uciok'){worker.postMessage('setoption name Hash value 16');worker.postMessage('setoption name MultiPV value 3');worker.postMessage('isready');}
            if(line==='readyok'){worker.postMessage('position fen '+fen);worker.postMessage('go movetime 1000');}
            if(line.startsWith('info ')&&line.includes(' pv ')&&!line.includes('lowerbound')&&!line.includes('upperbound')){
              const pv=line.match(/\bpv (.+)$/),value=line.match(/\bscore (cp|mate) (-?\d+)/),depth=Number(line.match(/\bdepth (\d+)/)?.[1]||0),rank=Number(line.match(/\bmultipv (\d+)/)?.[1]||1);
              if(!pv||!value||rank>3||(!checkingPlayed&&depth<(engineMoves[rank-1]?.depth||0)))continue;
              const trial=new Chess(fen),san=[];let first='';
              for(const uci of pv[1].trim().split(/\s+/).slice(0,6)){try{const move=trial.move({from:uci.slice(0,2),to:uci.slice(2,4),promotion:uci[4]});if(!move)break;if(!first)first=uci;san.push(move.san);}catch{break;}}
              if(!first)continue;
              const numeric=Number(value[2])*whiteSign,label=value[1]==='mate'?(numeric<0?'−M':'M')+Math.abs(numeric):(numeric>=0?'+':'')+(numeric/100).toFixed(2);
              const item={uci:first,san:san.join(' '),label,depth,kind:value[1],cp:Number(value[2])};
              if(checkingPlayed){
                if(first===playedMove.lan)comparison.textContent=describeMove(engineMoves[0],item,playedMove);
                continue;
              }
              engineMoves[rank-1]=item;
              const list=enginePanel.querySelector('[data-engine-lines]');list.replaceChildren();
              engineMoves.forEach(item=>{if(!item)return;const li=document.createElement('li');li.textContent=item.label+'  '+item.san;list.append(li);});
              if(engineMoves[0]){score.textContent=engineMoves[0].label;statusText.textContent='Depth '+engineMoves[0].depth+' · White advantage is positive';drawEngineArrow();}
            }
            if(line.startsWith('bestmove ')&&playedMove&&engineMoves[0]&&!checkingPlayed){
              const played=engineMoves.find(item=>item?.uci===playedMove.lan);
              comparison.textContent=describeMove(engineMoves[0],played,playedMove);
              if(!played){
                checkingPlayed=true;
                worker.postMessage('setoption name MultiPV value 1');
                worker.postMessage('position fen '+fen);
                worker.postMessage('go movetime 1000 searchmoves '+playedMove.lan);
                continue;
              }
            }
            if(line.startsWith('bestmove ')){clearTimeout(engineWatchdog);worker.terminate();if(engineWorker===worker)engineWorker=null;if(!engineMoves[0]){score.textContent='No line';statusText.textContent='No legal suggestion returned.';}}
          }
        };
        worker.postMessage('uci');
      }catch{fail();}
    },120);
  }
  engineToggle.querySelector('input').onchange=()=>{if(state.chess)updateChessAnalysis(review?.position||state.chess.game,state.chess);};
  window.addEventListener('hashchange',()=>{if(location.hash&&location.hash!=='#chess'){stopChessEngine();engineFen='';}else if(state.chess)updateChessAnalysis(review?.position||state.chess.game,state.chess);});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stopChessEngine();engineFen='';}else if(state.chess&&chessPane.checkVisibility())updateChessAnalysis(review?.position||state.chess.game,state.chess);});

  function schedule(id,fn){clearTimeout(timers[id]);timers[id]=setTimeout(()=>{if(!pane(id).checkVisibility()){schedule(id,fn);return;}fn();},500);}
  let Chess;
  try {({Chess}=await import('./vendor/chess/chess.js'));}catch {status('chess','Chess could not load. Reload to retry.');}
  let playingWorker=null,botWatchdog=0;
  function cancelBot(){
    clearTimeout(botWatchdog);
    if(playingWorker){playingWorker.terminate();playingWorker=null;}
  }
  function playComputer(s){
    const g=s.game,fen=g.fen();
    if(playingWorker)return;
    function apply(move){
      cancelBot();
      if(state.chess!==s||s.result||g.fen()!==fen||g.turn()!=='b')return;
      g.move(move);s.selected=null;renderBoard('chess');
    }
    const fallback=()=>apply(E.chessBotMove(g,s.strength));
    if(s.strength===500){fallback();return;}
    function unavailable(){
      cancelBot();
      status('chess','Chess engine unavailable. ');
      const retry=document.createElement('button');
      retry.type='button';retry.textContent='Retry bot move';
      retry.onclick=()=>renderBoard('chess');
      chessPane.querySelector('.ng-status').append(retry);
    }
    try{
      const worker=new Worker('/vendor/stockfish/stockfish-18-lite-single.js');
      playingWorker=worker;
      let min=1320,max=3190;
      worker.onerror=()=>{if(worker===playingWorker)unavailable();};
      botWatchdog=setTimeout(()=>{if(worker===playingWorker)unavailable();},15000);
      worker.onmessage=e=>{
        if(worker!==playingWorker)return;
        for(const line of String(e.data).split('\n')){
          const range=line.match(/option name UCI_Elo .*min (\d+) max (\d+)/);
          if(range){min=Number(range[1]);max=Number(range[2]);}
          if(line==='uciok'){
            if(s.strength<min&&Math.random()<(min-s.strength)/(min-500)){fallback();return;}
            worker.postMessage('setoption name UCI_LimitStrength value true');
            worker.postMessage('setoption name UCI_Elo value '+Math.min(max,Math.max(min,s.strength)));
            worker.postMessage('isready');
          }
          if(line==='readyok'){worker.postMessage('position fen '+fen);worker.postMessage('go movetime 500');}
          const best=line.match(/^bestmove ([a-h][1-8])([a-h][1-8])([qrbn])?/);
          if(best){apply({from:best[1],to:best[2],promotion:best[3]});return;}
        }
      };
      worker.postMessage('uci');
    }catch{unavailable();}
  }
  function newGame(id){
    const mode=pane(id).querySelector('[data-mode]')?.value;
    const strength=level.value==='custom'?custom.valueAsNumber:Number(level.value);
    if(id==='chess'){
      if(mode==='practice'&&level.value==='custom'&&!custom.reportValidity())return;
      review=null;archiveSelect.value='';cancelBot();
    }
    clearTimeout(timers[id]);state[id]={mode:mode==='practice'?'computer':mode,challenge:id==='chess'&&mode==='computer',strength,playerKey,selected:null};
    if(id==='chess'){if(!Chess)return;state[id].game=new Chess();refreshArchiveList(state[id]);}
    if(id==='checkers')state[id].game=new E.Checkers();
    if(id==='go')state[id].game=new E.Go();
    if(id==='poker'){state[id].game=new E.Poker();state[id].game.deal();state[id].held=new Set();}
    if(id==='euchre')state[id].game=new E.Euchre();
    if(id==='pool'){initPool();return;}render(id);
  }
  function render(id){if(['chess','checkers','go'].includes(id))renderBoard(id);else if(id==='poker')renderPoker();else if(id==='euchre')renderEuchre();}
  function renderBoard(id){const s=state[id],g=id==='chess'&&review?review.position:s.game,go=id==='go',chess=id==='chess',n=go?9:8;
    const ended=chess?!!s.result||g.isGameOver():!!g.result,turn=chess?g.turn()==='w'?1:-1:g.turn,human=s.mode==='local'||turn===1;
    const colour=chess?turn===1?'White':'Black':go?turn===1?'Black':'White':turn===1?'Red':'Black';
    const message=chess?(s.result||(g.isCheckmate()?(turn===1?'Black':'White')+' wins by checkmate':g.isDraw()?'Draw':colour+' to move'+(g.isCheck()?' — check':''))):g.result||colour+' to move'+(!go&&g.chain!==null?' — continue capture':'');
    status(id,chess&&review?'Review · '+(g.turn()==='w'?'White':'Black')+' to move':message+(!ended&&!human?' · Computer thinking…':''));
    const selected=chess&&review?null:s.selected,legal=chess?(selected?g.moves({square:selected,verbose:true}).map(m=>m.to):[]):go?[]:g.moves().filter(m=>m.from===selected).map(m=>m.to);
    const chessPiece=p=>`<span class="ng-chess-piece ${p.color==='w'?'white':'black'} piece-${p.type}" aria-hidden="true"></span>`;
    const play=pane(id).querySelector('.ng-play'),existing=chess&&play.querySelector('.ng-board');
    let html=`<div class="ng-board ${chess?'chess':go?'go':''}" aria-label="${titles[id]} board">`;
    for(let i=0;i<n*n;i++){const r=Math.floor(i/n),c=i%n,key=chess?'abcdefgh'[c]+(8-r):i,p=chess?g.get(key):g.board[i],label=chess?key:'ABCDEFGHJ'[c]+(n-r);
      const content=chess?p?chessPiece(p,key):'':go?p?`<span class="ng-stone ${p<0?'white':''}"></span>`:'':p?`<span class="ng-piece ${p<0?'black':''}">${Math.abs(p)===2?'K':''}</span>`:'';
      const desc=chess?p?(p.color==='w'?'White ':'Black ')+({p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen',k:'king'}[p.type]):'empty':p?(go?(p>0?'Black stone':'White stone'):(p>0?'Red':'Black')+(Math.abs(p)===2?' king':' piece')):'empty';
      if(existing){
        const square=existing.children[i],name=label+', '+desc;
        square.classList.toggle('selected',selected===key);
        square.classList.toggle('legal',legal.includes(key));
        square.classList.remove('ng-last-move','ng-drag-source','ng-drop-target');
        square.disabled=ended||!human||!!review;
        if(square.getAttribute('aria-label')!==name){
          square.setAttribute('aria-label',name);
          square.innerHTML=content;
        }
        continue;
      }
      html+=`<button type="button" class="ng-square ${(r+c)%2?'dark':''} ${selected===key?'selected':''} ${legal.includes(key)?'legal':''}" data-square="${key}" aria-label="${label}, ${desc}" ${ended||!human?'disabled':''}>${content}${(!go&&!chess)?`<small>${label}</small>`:''}</button>`;
    }
    html+='</div>';if(go)html+=`<div class="ng-toolbar"><button type="button" data-pass ${ended||!human?'disabled':''}>Pass</button><span>Captured · Black ${g.captured[0]} / White ${g.captured[1]}</span></div>`;
    if(chess){html=`<div class="ng-chess-frame"><div class="ng-ranks" aria-hidden="true">${[8,7,6,5,4,3,2,1].map(rank=>`<span>${rank}</span>`).join('')}</div>${html}<div class="ng-files" aria-hidden="true">${[...'abcdefgh'].map(file=>`<span>${file}</span>`).join('')}</div></div>`;renderChessHistory(s.game,s);saveReviewGame(s,s.game.history({verbose:true}));updateReviewControls(s);}
    if(!existing)play.innerHTML=html;
    if(chess){
      const last=g.history({verbose:true}).at(-1);
      const fen=g.fen();
      if(existing&&s.drawnFen&&fen!==s.drawnFen&&last?.after===fen&&last.before===s.drawnFen&&!s.justDragged&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
        const piece=existing.querySelector('[data-square="'+last.to+'"] .ng-chess-piece');
        const cell=existing.children[0].getBoundingClientRect();
        const dx=(last.from.charCodeAt(0)-last.to.charCodeAt(0))*cell.width;
        const dy=(Number(last.to[1])-Number(last.from[1]))*cell.height;
        if(piece){
          const anim=piece.animate([{transform:'translate('+dx+'px,'+dy+'px)'},{transform:'none'}],{duration:150,easing:'ease-out'});
          const square=piece.parentElement;
          square.classList.add('ng-moving');
          anim.onfinish=anim.oncancel=()=>square.classList.remove('ng-moving');
        }
      }
      s.drawnFen=fen;s.justDragged=false;
      if(ended&&!review)advance(s);
    }
    if(chess&&toolbar.querySelector('[data-last-move]').checked){const last=g.history({verbose:true}).at(-1);if(last)for(const square of [last.from,last.to])chessPane.querySelector(`[data-square="${square}"]`).classList.add('ng-last-move');}
    pane(id).querySelectorAll('[data-square]').forEach(b=>b.onclick=()=>{
      const to=chess?b.dataset.square:Number(b.dataset.square);let moved=false;
      if(go)moved=g.move(to);
      else if(chess){if(selected&&legal.includes(to)){g.move({from:selected,to,promotion:pane(id).querySelector('[data-promotion]').value});moved=true;}else s.selected=g.get(to)?.color===g.turn()?to:null;}
      else if(selected!==null&&legal.includes(to))moved=g.move(selected,to);else s.selected=Math.sign(g.board[to])===g.turn?to:null;
      if(moved)s.selected=!chess&&!go?g.chain:null;renderBoard(id);if(go&&!moved)status(id,'Illegal move: occupied point, suicide, or repeated position.');
    });
    pane(id).querySelector('[data-pass]')?.addEventListener('click',()=>{g.pass();renderBoard(id);});
    if(chess){bindChessDrag();updateChessAnalysis(g,s);}
    if(!ended&&!human&&!(chess&&review))schedule(id,()=>{if(chess){playComputer(s);return;}else if(go){const legal=g.board.map((_,i)=>({i,m:g.candidate(i)})).filter(x=>x.m);if(g.passes||!legal.length)g.pass();else{legal.forEach(x=>x.v=x.m.count*5+Math.random()+(g.neighbors(x.i).some(j=>g.board[j])?.25:0));legal.sort((a,b)=>b.v-a.v);g.move(legal[0].i);}}else{const moves=g.moves();const m=moves[Math.floor(Math.random()*moves.length)];g.move(m.from,m.to);}s.selected=null;renderBoard(id);});
  }
  function bindChessDrag(){
    const board=chessPane.querySelector('.ng-board');
    if(board.dataset.dragBound)return;
    board.dataset.dragBound='true';
    let drag=null,suppressClick=false;
    board.addEventListener('dragstart',event=>event.preventDefault());
    function squareAt(event){
      const rect=board.getBoundingClientRect();
      const col=Math.floor((event.clientX-rect.left)*8/rect.width);
      const row=Math.floor((event.clientY-rect.top)*8/rect.height);
      return col>=0&&col<8&&row>=0&&row<8?board.querySelector('[data-square="'+'abcdefgh'[col]+(8-row)+'"]'):null;
    }
    board.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopImmediatePropagation();suppressClick=false;}},true);
    board.addEventListener('pointerdown',event=>{
      const s=state.chess,g=s.game;
      if(review||event.button!==0||drag||s.result||g.isGameOver()||(s.mode==='computer'&&g.turn()==='b'))return;
      const square=event.target.closest('[data-square]'),from=square?.dataset.square;
      if(!from||g.get(from)?.color!==g.turn())return;
      drag={id:event.pointerId,from,square,x:event.clientX,y:event.clientY,fen:g.fen(),legal:g.moves({square:from,verbose:true}).map(m=>m.to),ghost:null};

    });
    board.addEventListener('pointermove',event=>{
      if(!drag||drag.id!==event.pointerId)return;
      if(!drag.ghost&&Math.hypot(event.clientX-drag.x,event.clientY-drag.y)<5)return;
      event.preventDefault();
      if(!drag.ghost){
        drag.square.setPointerCapture(event.pointerId);
        const size=drag.square.getBoundingClientRect().width;
        drag.ghost=drag.square.firstElementChild.cloneNode(true);
        drag.ghost.classList.add('ng-drag-ghost');
        drag.ghost.style.cssText=`position:fixed;width:${size}px;height:${size}px;z-index:10000;pointer-events:none;`;
        board.append(drag.ghost);drag.square.classList.add('ng-drag-source');
        board.querySelectorAll('[data-square]').forEach(el=>{el.classList.toggle('legal',drag.legal.includes(el.dataset.square));el.classList.toggle('selected',el===drag.square);});
      }
      drag.ghost.style.left=(event.clientX-drag.ghost.offsetWidth/2)+'px';
      drag.ghost.style.top=(event.clientY-drag.ghost.offsetHeight/2)+'px';
      const target=squareAt(event);
      board.querySelectorAll('.ng-drop-target').forEach(el=>el.classList.remove('ng-drop-target'));
      if(target&&board.contains(target)&&drag.legal.includes(target.dataset.square))target.classList.add('ng-drop-target');
    });
    function finish(event,cancelled=false){
      if(!drag||event.pointerId!==drag.id)return;
      const s=state.chess,g=s.game;
      const current=drag;drag=null;
      if(current.square.hasPointerCapture(current.id))current.square.releasePointerCapture(current.id);
      if(!current.ghost)return;
      suppressClick=true;setTimeout(()=>{suppressClick=false;},0);current.ghost.remove();
      const target=squareAt(event);
      if(!cancelled&&target&&board.contains(target)&&g.fen()===current.fen&&current.legal.includes(target.dataset.square)){
        s.justDragged=true;g.move({from:current.from,to:target.dataset.square,promotion:chessPane.querySelector('[data-promotion]').value});s.selected=null;
      }else s.selected=current.from;
      renderBoard('chess');
    }
    board.addEventListener('pointerup',event=>finish(event));
    board.addEventListener('pointercancel',event=>finish(event,true));
    board.addEventListener('lostpointercapture',event=>finish(event,true));
  }

  const pokerNames=['High card','Pair','Two pair','Three of a kind','Straight','Flush','Full house','Four of a kind','Straight flush'];
  function renderPoker(){const s=state.poker,g=s.game,done=g.phase==='done';status('poker',g.result);pane('poker').querySelector('.ng-play').innerHTML=`<div class="ng-score">You: ${g.chips[0]} · Computer: ${g.chips[1]} play chips</div><div class="ng-table">Computer${done?' · '+pokerNames[E.pokerRank(g.hands[1])[0]]:''}<div class="ng-hand">${g.hands[1].map((c,i)=>card(c,i,false,!done,true)).join('')}</div></div><p>Your hand${done?' · '+pokerNames[E.pokerRank(g.hands[0])[0]]:''}</p><div class="ng-hand" data-hand>${g.hands[0].map((c,i)=>card(c,i,s.held.has(i),false,done)).join('')}</div><div class="ng-toolbar"><button type="button" data-draw ${done?'disabled':''}>${s.held.size?'Replace '+s.held.size+' and reveal':'Stand pat and reveal'}</button><button type="button" data-deal ${!done||Math.min(...g.chips)<5?'disabled':''}>Next hand · ante 5</button></div>${Math.min(...g.chips)<5&&done?'<p>Match finished. Start a new game to reset the play chips.</p>':''}`;
    pane('poker').querySelectorAll('[data-hand] [data-card]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.card);s.held.has(i)?s.held.delete(i):s.held.add(i);renderPoker();});
    pane('poker').querySelector('[data-draw]').onclick=()=>{g.draw([...s.held]);s.held.clear();renderPoker();};pane('poker').querySelector('[data-deal]').onclick=()=>{g.deal();renderPoker();};
  }
  const seats=['You','East','North (partner)','West'];
  function renderEuchre(){const g=state.euchre.game,human=g.turn===0,playing=['bid','discard','play'].includes(g.phase);status('euchre',g.result||(g.phase==='bid'?`${seats[g.turn]} to call trump · round ${g.round}`:g.phase==='discard'?`${seats[g.turn]} must discard one card`:`${seats[g.turn]} to play`));
    const table=g.table.length?g.table:g.last;
    const seatPanel=i=>`<div class="eu-seat eu-seat-${i} ${playing&&g.turn===i?'is-turn':''} ${g.skipped===i?'is-out':''}"><strong>${seats[i]}</strong><small>${i%2===0?'Your team':'Opponents'}${g.dealer===i?' · Dealer':''}${g.maker===i?' · Maker':''}</small><span>${g.skipped===i?'Sitting out':g.hands[i].length+' cards'}${playing&&g.turn===i?' · Current turn':''}</span></div>`;
    const hint=g.phase==='bid'?(human?'Choose trump or pass.':'Waiting for '+seats[g.turn]+' to bid.') :g.phase==='discard'?(human?'Choose one card to discard.':'Dealer is discarding.') :g.phase==='play'?(g.skipped===0?'You are sitting out while your partner plays alone.':human?'Your turn — choose a highlighted card. Follow suit when possible.':'Waiting for '+seats[g.turn]+'.') :'Hand complete';
    let html=`<div class="eu-scoreboard" aria-label="Match score"><div><small>YOU + NORTH</small><strong>${g.scores[0]} <span>/ 10</span></strong><span>${g.tricks[0]} tricks this hand</span></div><div class="eu-trump"><small>TRUMP</small><strong>${g.trump?symbol[g.trump]:'—'}</strong><span>${g.trump?(g.alone?'Going alone':'Team play'):'Bidding · Round '+g.round}</span></div><div><small>EAST + WEST</small><strong>${g.scores[1]} <span>/ 10</span></strong><span>${g.tricks[1]} tricks this hand</span></div></div><div class="eu-felt" aria-label="Euchre table">${[2,3,1,0].map(seatPanel).join('')}<div class="eu-centre"><small>${g.phase==='bid'?'TURNED CARD':g.table.length?'CURRENT TRICK':g.last.length?'LAST TRICK':'READY TO PLAY'}</small><div class="eu-trick">${g.phase==='bid'?card(g.up,0,false,false,true):table.map((x,i)=>`<div class="eu-played"><span>${seats[x.player]}</span>${card(x.card,i,false,false,true)}</div>`).join('')}</div></div></div><div class="eu-controls"><p class="eu-hint">${hint}</p>`;
    if(g.phase==='bid'&&human)html+=`<div class="ng-toolbar">${g.suits().map(s=>`<button type="button" data-bid="${s}">${g.round===1?'Order up':'Call'} ${symbol[s]}</button>`).join('')}<button type="button" data-bid="" ${g.round===2&&g.passed===3?'disabled':''}>Pass</button><label><input type="checkbox" data-alone> Go alone</label></div>`;
    const legal=g.phase==='play'&&human?g.legal():[];
    html+=`<div class="eu-hand-heading"><strong>Your hand</strong><span>${g.skipped===0?'Sitting out':g.phase==='discard'&&human?'Select a discard':g.phase==='play'&&human?'Playable cards highlighted':'South · You'}</span></div><div class="ng-hand" data-hand>${g.hands[0].map((c,i)=>card(c,i,false,false,!human||!(g.phase==='discard'||g.phase==='play'&&legal.includes(i)))).join('')}</div>`;
    if(g.phase==='done')html+='<button type="button" data-next>Deal next hand →</button>';if(g.phase==='over')html+=`<p class="eu-match-result">${g.scores[0]>=10?'Your team wins the match!':'Opponents win the match.'}</p>`;
    html+='</div>';
    pane('euchre').querySelector('.ng-play').innerHTML=html;
    pane('euchre').querySelectorAll('[data-bid]').forEach(b=>b.onclick=()=>{g.bid(b.dataset.bid||null,pane('euchre').querySelector('[data-alone]').checked);renderEuchre();});
    pane('euchre').querySelectorAll('[data-hand] [data-card]').forEach(b=>b.onclick=()=>{g.phase==='discard'?g.discard(Number(b.dataset.card)):g.play(Number(b.dataset.card));renderEuchre();});
    pane('euchre').querySelector('[data-next]')?.addEventListener('click',()=>{g.next();renderEuchre();});if(playing&&!human)schedule('euchre',()=>{g.ai();renderEuchre();});
  }
  let animation=0;
  function initPool(){cancelAnimationFrame(animation);clearTimeout(timers.pool);const s=state.pool;s.shots=[0,0];s.scores=[0,0];s.scratches=[0,0];s.turn=0;s.moving=false;s.balls=[{x:180,y:200,vx:0,vy:0,n:0}];for(let r=0,k=1;r<4;r++)for(let c=0;c<=r;c++)s.balls.push({x:510+r*19,y:200+(c-r/2)*22,vx:0,vy:0,n:k++});
    pane('pool').querySelector('.ng-play').innerHTML='<canvas class="ng-pool" width="800" height="400" aria-label="Pool table: use angle, power and Shoot controls"></canvas><div class="ng-toolbar"><label>Angle <input data-angle type="range" min="0" max="359" value="0"> <output data-angle-value>0°</output></label><label>Power <input data-power type="range" min="1" max="100" value="60"></label><button type="button" data-shoot>Shoot</button></div>';
    const canvas=pane('pool').querySelector('canvas'),ctx=canvas.getContext('2d'),angle=pane('pool').querySelector('[data-angle]'),power=pane('pool').querySelector('[data-power]'),shoot=pane('pool').querySelector('[data-shoot]');
    const pockets=[[13,13],[400,10],[787,13],[13,387],[400,390],[787,387]],colours=['#faf6e9','#e5ba37','#448bcd','#ce514b','#9667c9','#df863b','#56a88e','#a14462','#24262b','#e5ba37','#448bcd'];
    function draw(){ctx.clearRect(0,0,800,400);ctx.fillStyle='#184c3b';ctx.fillRect(0,0,800,400);pockets.forEach(([x,y])=>{ctx.beginPath();ctx.arc(x,y,19,0,7);ctx.fillStyle='#0b1817';ctx.fill();});const cue=s.balls.find(b=>!b.n&&!b.pocket),count=s.balls.filter(b=>b.n&&b.pocket).length,done=count===10,human=s.mode==='local'||s.turn===0;if(cue&&!s.moving&&human&&!done){const a=Number(angle.value)*Math.PI/180;ctx.beginPath();ctx.moveTo(cue.x,cue.y);ctx.lineTo(cue.x+Math.cos(a)*120,cue.y+Math.sin(a)*120);ctx.strokeStyle='#e7e7c6';ctx.setLineDash([6,6]);ctx.stroke();ctx.setLineDash([]);}s.balls.filter(b=>!b.pocket).forEach(b=>{ctx.beginPath();ctx.arc(b.x,b.y,10,0,7);ctx.fillStyle=colours[b.n];ctx.fill();ctx.strokeStyle='#111';ctx.stroke();if(b.n){ctx.fillStyle=b.n===8?'white':'#101b22';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText(b.n,b.x,b.y+4);}});shoot.disabled=s.moving||done||!human;angle.disabled=power.disabled=s.moving||done||!human;if(s.mode==='local')status('pool',`${done?'Table cleared! · ':''}${count}/10 pocketed · ${s.shots[0]} shots · ${s.scratches[0]} scratches${s.moving?' · Balls moving':''}`);else{const result=s.scores[0]===s.scores[1]?'Tie game':s.scores[0]>s.scores[1]?'You win!':'NorthStar Bot wins';status('pool',`You ${s.scores[0]} · Bot ${s.scores[1]}${done?' · '+result:s.moving?' · Balls moving':s.turn?' · Bot thinking…':' · Your turn'} · Shots ${s.shots[0]}–${s.shots[1]}`);}}
    function tick(){if(!pane('pool').checkVisibility()){animation=requestAnimationFrame(tick);return;}for(let step=0;step<3;step++){
      const active=s.balls.filter(b=>!b.pocket);for(const b of active){b.x+=b.vx/3;b.y+=b.vy/3;b.vx*=.992;b.vy*=.992;if(Math.hypot(b.vx,b.vy)<.06)b.vx=b.vy=0;if(pockets.some(([x,y])=>Math.hypot(b.x-x,b.y-y)<20)){b.pocket=true;b.vx=b.vy=0;if(!b.n)s.scratches[s.turn]++;else s.scores[s.turn]++;continue;}if(b.x<12||b.x>788){b.x=Math.max(12,Math.min(788,b.x));b.vx*=-.9;}if(b.y<12||b.y>388){b.y=Math.max(12,Math.min(388,b.y));b.vy*=-.9;}}
      for(let i=0;i<active.length;i++)for(let j=i+1;j<active.length;j++){const a=active[i],b=active[j];if(a.pocket||b.pocket)continue;const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d>0&&d<20){const nx=dx/d,ny=dy/d,overlap=(20-d)/2;a.x-=nx*overlap;a.y-=ny*overlap;b.x+=nx*overlap;b.y+=ny*overlap;const v=(a.vx-b.vx)*nx+(a.vy-b.vy)*ny;if(v>0){a.vx-=v*nx;a.vy-=v*ny;b.vx+=v*nx;b.vy+=v*ny;}}}
    }s.moving=s.balls.some(b=>!b.pocket&&(b.vx||b.vy));if(!s.moving){const cue=s.balls[0];if(cue.pocket){let spot;for(let x=80;x<780&&!spot;x+=24)for(let y=40;y<380&&!spot;y+=24)if(s.balls.every(b=>b===cue||b.pocket||Math.hypot(b.x-x,b.y-y)>22))spot={x,y};Object.assign(cue,spot,{pocket:false});}if(s.mode==='computer'&&s.balls.some(b=>b.n&&!b.pocket)){s.turn=1-s.turn;if(s.turn===1)schedule('pool',botShot);}}draw();if(s.moving)animation=requestAnimationFrame(tick);}
    function takeShot(){if(s.moving||s.balls.every(b=>!b.n||b.pocket))return;const a=Number(angle.value)*Math.PI/180;s.balls[0].vx=Math.cos(a)*Number(power.value)*.16;s.balls[0].vy=Math.sin(a)*Number(power.value)*.16;s.shots[s.turn]++;s.moving=true;tick();}
    function botShot(){const shot=E.poolBotShot(s.balls,pockets);if(!shot)return;angle.value=Math.round(shot.angle);power.value=Math.round(shot.power);pane('pool').querySelector('[data-angle-value]').textContent=angle.value+'°';takeShot();}
    angle.oninput=()=>{pane('pool').querySelector('[data-angle-value]').textContent=angle.value+'°';draw();};canvas.onpointerdown=e=>{if(s.moving||s.mode==='computer'&&s.turn===1)return;const box=canvas.getBoundingClientRect(),cue=s.balls[0],a=Math.atan2((e.clientY-box.top)*400/box.height-cue.y,(e.clientX-box.left)*800/box.width-cue.x)*180/Math.PI;angle.value=Math.round((a+360)%360);angle.oninput();};shoot.onclick=takeShot;draw();
  }
  Object.keys(titles).forEach(id=>{pane(id).querySelector('[data-new]').onclick=()=>{if(id==='chess'&&(!state.chess.game.history().length||state.chess.result||state.chess.game.isGameOver())||confirm('Start a new '+titles[id]+' game? Current progress will be lost.'))newGame(id);};if(id!=='chess')pane(id).querySelector('[data-mode]')?.addEventListener('change',()=>newGame(id));newGame(id);});
  window.NorthstarGames={state,newGame};
})();
